SELECT ec."full_name"
FROM "executive_chef" AS ec
ORDER BY ec."full_name" ASC NULLS FIRST;

337:
SELECT DISTINCT sc."full_name"
FROM "sous_chef" sc
ORDER BY sc."full_name" ASC NULLS FIRST;

